ga3k(){return"\u062a\u0639\u0630\u0631 \u062a\u062d\u0645\u064a\u0644 \u0627\u0644\u0631\u0639\u0627\u064a\u0627\u062a"},
ga3l(){return"\u0641\u0634\u0644 \u0627\u0644\u062a\u0648\u0642\u064a\u0639 \u2014 \u062d\u0627\u0648\u0644 \u0645\u062c\u062f\u062f\u064b\u0627"},
gtb(){return"\u0627\u0644\u0631\u0639\u0627\u064a\u0627\u062a"},
gTP(){return"\u0627\u0644\u0645\u0624\u062a\u0645\u0631 \u0627\u0644\u0635\u062d\u0641\u064a"},
gaSU(){return"\u0648\u0627\u062b\u0642"},
gaSV(){return"\u0627\u0644\u062e\u0635\u0645 \u0633\u064a\u0633\u0645\u0639 \u0630\u0644\u0643"},
