gaSA(){return"\u0628\u0639\u062f \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629"},
gaSE(){return"\u0642\u0628\u0644 \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629"},
gaSL(){return"\u0627\u0644\u0642\u0627\u0639\u0629 \u0645\u0641\u062a\u0648\u062d\u0629"},
gaT2(){return"\u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u0641\u064a \u0627\u0646\u062a\u0638\u0627\u0631\u0643"},
gaT1(){return"\u0627\u0644\u0645\u0647\u0644\u0629 \u062a\u0648\u0634\u0643 \u0639\u0644\u0649 \u0627\u0644\u0627\u0646\u062a\u0647\u0627\u0621 \u2014 \u0625\u0646 \u0644\u0645 \u062a\u062d\u0636\u0631 \u062a\u0643\u062a\u0628 \u0627\u0644\u0635\u062d\u0627\u0641\u0629 \xab\u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0641\u0646\u064a \u0644\u0645 \u064a\u0648\u0627\u062c\u0647 \u0627\u0644\u0635\u062d\u0627\u0641\u0629\xbb."},
