gaSu(){return"\u0625\u0644\u0649 \u0622\u062e\u0631 \u0627\u0644\u0623\u062e\u0628\u0627\u0631"},
gaWk(){return"\u0644\u0627 \u0631\u062c\u0639\u0629 \u0641\u064a\u0647"},
gaWl(){return"\u062a\u0623\u0643\u064a\u062f \u0627\u0644\u0625\u0639\u0644\u0627\u0646"},
gaWm(){return"\u0625\u0630\u0627 \u0648\u0631\u062f \u0639\u0631\u0636 \u0648\u0627\u062d\u062f \u0628\u0647\u0630\u0627 \u0627\u0644\u0633\u0639\u0631 \u064a\u064f\u0628\u0627\u0639 \u0627\u0644\u0644\u0627\u0639\u0628. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0633\u062d\u0628 \u0627\u0644\u0625\u0639\u0644\u0627\u0646."},
